const config = $input.first()?.json || {};
const rawSourcesJson = (config.rssSourcesJson || '').trim();
const fallbackSources = [
  {
    feedUrl: 'http://rsshub:1200/xiaoyuzhou/podcast/648b0b641c48983391a63f98?limit=1',
    sourceName: '42\u7ae0\u7ecf',
    sourceType: 'podcast'
  }
];

const parseOptionalBoolean = (...values) => {
  for (const value of values) {
    if (value === true || value === false) {
      return value;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      if (value === 1) {
        return true;
      }
      if (value === 0) {
        return false;
      }
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        continue;
      }
      if (['true', '1', 'yes', 'y', 'on'].includes(normalized)) {
        return true;
      }
      if (['false', '0', 'no', 'n', 'off'].includes(normalized)) {
        return false;
      }
    }
  }
  return null;
};

let sources = fallbackSources;
if (rawSourcesJson) {
  try {
    const parsed = JSON.parse(rawSourcesJson);
    if (!Array.isArray(parsed)) {
      throw new Error('RSS_SOURCE_URLS_JSON must be a JSON array');
    }
    sources = parsed;
  } catch (error) {
    throw new Error(`RSS_SOURCE_URLS_JSON parse failed: ${error.message}`);
  }
}

const obsidianInboxDir = (config.obsidianInboxDir || '00_Inbox').trim() || '00_Inbox';

return sources.map((source, index) => {
  const feedUrl = (source.feedUrl || source.url || '').trim();
  if (!feedUrl) {
    throw new Error(`Source ${index + 1} is missing feedUrl/url`);
  }

  const transcriptPollIntervalMs = Number(source.transcriptPollIntervalMs || 0);
  const transcriptMaxPolls = Number(source.transcriptMaxPolls || 0);
  const maxItems = Number(source.maxItems || source.max_items || 0);
  const useSpeakerRecognition = parseOptionalBoolean(
    source.useSpeakerRecognition,
    source.use_speaker_recognition
  );

  return {
    json: {
      feedUrl,
      sourceName: source.sourceName || source.name || `source-${index + 1}`,
      sourceType: source.sourceType || 'rss',
      routeToTranscript: typeof source.routeToTranscript === 'boolean' ? source.routeToTranscript : null,
      useSpeakerRecognition,
      transcriptPollIntervalMs: Number.isFinite(transcriptPollIntervalMs) ? transcriptPollIntervalMs : 0,
      transcriptMaxPolls: Number.isFinite(transcriptMaxPolls) ? transcriptMaxPolls : 0,
      maxItems: Number.isFinite(maxItems) && maxItems > 0 ? Math.floor(maxItems) : 0,
      obsidianInboxDir
    }
  };
});

const metadata = $input.item.json && typeof $input.item.json === 'object' ? $input.item.json : {};
const sourceContext = (() => {
  try {
    return $('Feed Sources').item.json || {};
  } catch {
    return {};
  }
})();

const parseOptionalBoolean = (...values) => {
  for (const value of values) {
    if (value === true || value === false) {
      return value;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      if (value === 1) {
        return true;
      }
      if (value === 0) {
        return false;
      }
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        continue;
      }
      if (['true', '1', 'yes', 'y', 'on'].includes(normalized)) {
        return true;
      }
      if (['false', '0', 'no', 'n', 'off'].includes(normalized)) {
        return false;
      }
    }
  }
  return null;
};

const sourcePayload = {
  feedUrl: String(sourceContext.feedUrl || '').trim(),
  sourceName: String(sourceContext.sourceName || '').trim(),
  sourceType: String(sourceContext.sourceType || 'rss').trim() || 'rss',
  routeToTranscript: typeof sourceContext.routeToTranscript === 'boolean' ? sourceContext.routeToTranscript : null,
  useSpeakerRecognition: parseOptionalBoolean(
    sourceContext.useSpeakerRecognition,
    sourceContext.use_speaker_recognition
  ),
  transcriptPollIntervalMs: Number(sourceContext.transcriptPollIntervalMs || 0) || 0,
  transcriptMaxPolls: Number(sourceContext.transcriptMaxPolls || 0) || 0,
  obsidianInboxDir: String(sourceContext.obsidianInboxDir || '00_Inbox').trim() || '00_Inbox'
};

if (typeof metadata.error === 'string' && metadata.error.trim()) {
  return {
    json: {
      ok: false,
      stage: 'rss_read',
      error: metadata.error.trim(),
      ...sourcePayload
    }
  };
}

return {
  json: {
    ok: true,
    ...sourcePayload,
    ...metadata
  }
};

const getSourceKey = ({ feedUrl = '', sourceName = '', sourceType = '' } = {}) => {
  const normalizedFeedUrl = String(feedUrl || '').trim();
  const normalizedSourceName = String(sourceName || '').trim();
  const normalizedSourceType = String(sourceType || '').trim();
  if (normalizedFeedUrl) {
    return normalizedFeedUrl;
  }
  if (normalizedSourceName || normalizedSourceType) {
    return `${normalizedSourceName}::${normalizedSourceType}`;
  }
  return '';
};

const parseOptionalBoolean = (...values) => {
  for (const value of values) {
    if (value === true || value === false) {
      return value;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      if (value === 1) {
        return true;
      }
      if (value === 0) {
        return false;
      }
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        continue;
      }
      if (['true', '1', 'yes', 'y', 'on'].includes(normalized)) {
        return true;
      }
      if (['false', '0', 'no', 'n', 'off'].includes(normalized)) {
        return false;
      }
    }
  }
  return null;
};

const createSourceEntry = ({ feedUrl = '', sourceName = '', sourceType = '', routeToTranscript = null, useSpeakerRecognition = null, transcriptPollIntervalMs = 0, transcriptMaxPolls = 0, maxItems = 0, obsidianInboxDir = '00_Inbox' } = {}) => ({
  feedUrl: String(feedUrl || '').trim(),
  sourceName: String(sourceName || '').trim(),
  sourceType: String(sourceType || '').trim() || 'rss',
  routeToTranscript: typeof routeToTranscript === 'boolean' ? routeToTranscript : null,
  useSpeakerRecognition: parseOptionalBoolean(useSpeakerRecognition),
  transcriptPollIntervalMs: Number(transcriptPollIntervalMs || 0) || 0,
  transcriptMaxPolls: Number(transcriptMaxPolls || 0) || 0,
  maxItems: Number(maxItems || 0) > 0 ? Math.floor(Number(maxItems || 0)) : 0,
  obsidianInboxDir: String(obsidianInboxDir || '00_Inbox').trim() || '00_Inbox',
  rss_status: 'success',
  rss_error: '',
  rss_items: []
});

const groupedBySource = new Map();
try {
  for (const sourceItem of $('Feed Sources').all()) {
    const sourceData = sourceItem.json && typeof sourceItem.json === 'object' ? sourceItem.json : {};
    const sourceKey = getSourceKey({
      feedUrl: sourceData.feedUrl,
      sourceName: sourceData.sourceName,
      sourceType: sourceData.sourceType
    });
    if (!sourceKey) {
      continue;
    }
    groupedBySource.set(sourceKey, createSourceEntry(sourceData));
  }
} catch {}

for (const item of $input.all()) {
  const data = item.json && typeof item.json === 'object' ? item.json : {};
  const sourceKey = getSourceKey({
    feedUrl: data.feedUrl || data.feed_url,
    sourceName: data.sourceName || data.source_name,
    sourceType: data.sourceType || data.source_type
  });
  if (!sourceKey) {
    continue;
  }
  const existing = groupedBySource.get(sourceKey) || createSourceEntry(data);
  if (data.ok === false && String(data.stage || '').trim() === 'rss_read') {
    existing.rss_status = 'error';
    existing.rss_error = String(data.error || 'unknown RSS read error').trim() || 'unknown RSS read error';
    existing.rss_items = [];
  } else if (data.ok !== false) {
    if (!existing.maxItems || existing.rss_items.length < existing.maxItems) {
      existing.rss_items.push(data);
    }
  }
  groupedBySource.set(sourceKey, existing);
}

return Array.from(groupedBySource.values()).map((entry) => ({ json: entry }));

const sourceContext = $json && typeof $json === 'object' ? $json : {};

const rawHtml = [
  $json['content:encoded'],
  $json.content,
  $json.contentSnippet,
  $json.summary,
  $json.description
].find((value) => typeof value === 'string' && value.trim()) || '';
const description = [
  $json.contentSnippet,
  $json.summary,
  $json.description
].find((value) => typeof value === 'string' && value.trim()) || '';
const sourceType = String(sourceContext.sourceType || sourceContext.source_type || 'rss').trim() || 'rss';
const canonicalUrl = String($json.link || $json.guid || '').trim();
const lowerSourceType = sourceType.toLowerCase();

const parseOptionalBoolean = (...values) => {
  for (const value of values) {
    if (value === true || value === false) {
      return value;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      if (value === 1) {
        return true;
      }
      if (value === 0) {
        return false;
      }
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        continue;
      }
      if (['true', '1', 'yes', 'y', 'on'].includes(normalized)) {
        return true;
      }
      if (['false', '0', 'no', 'n', 'off'].includes(normalized)) {
        return false;
      }
    }
  }
  return null;
};

const collectEnclosureCandidates = (value) => {
  if (!value) {
    return [];
  }
  if (typeof value === 'string') {
    return [{ url: value.trim(), type: '' }].filter((item) => item.url);
  }
  if (Array.isArray(value)) {
    return value.flatMap(collectEnclosureCandidates);
  }
  if (typeof value === 'object') {
    const url = [value.url, value.link, value.href, value.src]
      .find((candidate) => typeof candidate === 'string' && candidate.trim()) || '';
    const type = [value.type, value.mimeType]
      .find((candidate) => typeof candidate === 'string' && candidate.trim()) || '';
    return url ? [{ url: url.trim(), type: type.trim() }] : [];
  }
  return [];
};

const enclosureCandidates = collectEnclosureCandidates($json.enclosure);
const audioEnclosure = enclosureCandidates.find((item) => /(^audio\/)|\.(mp3|m4a|aac|wav|ogg)(\?|$)/i.test(`${item.type} ${item.url}`));
const transcriptSourceUrl = canonicalUrl || String(audioEnclosure?.url || '').trim();
const isPodcastSource = ['podcast', 'audio', 'podcast_rss'].includes(lowerSourceType);
const isXiaoyuzhouEpisode = /https?:\/\/(?:www\.)?xiaoyuzhoufm\.com\/episode\//i.test(transcriptSourceUrl);
const explicitRouteToTranscript = typeof sourceContext.routeToTranscript === 'boolean'
  ? sourceContext.routeToTranscript
  : (typeof sourceContext.route_to_transcript === 'boolean' ? sourceContext.route_to_transcript : null);
const explicitUseSpeakerRecognition = parseOptionalBoolean(
  sourceContext.useSpeakerRecognition,
  sourceContext.use_speaker_recognition
);
const routeToTranscript = explicitRouteToTranscript ?? Boolean(isPodcastSource || isXiaoyuzhouEpisode || audioEnclosure?.url);
const transcriptPollIntervalMs = Number(sourceContext.transcriptPollIntervalMs || sourceContext.transcript_poll_interval_ms || 0) || 0;
const transcriptMaxPolls = Number(sourceContext.transcriptMaxPolls || sourceContext.transcript_max_polls || 0) || 0;
const extraTags = ['raw-ingest'];
if (routeToTranscript) {
  extraTags.push('transcript-route');
}

return {
  json: {
    source_type: sourceType,
    feed_url: String(sourceContext.feedUrl || sourceContext.feed_url || '').trim(),
    source_name: String(sourceContext.sourceName || sourceContext.source_name || sourceContext.name || '').trim(),
    canonical_url: canonicalUrl,
    original_id: String($json.guid || $json.id || $json.link || transcriptSourceUrl).trim(),
    title: (($json.title || '').trim() || 'untitled'),
    author: (($json.creator || $json.author || '').trim()),
    published_at: $json.isoDate || $json.pubDate || new Date().toISOString(),
    media_type: routeToTranscript ? 'audio' : 'text',
    raw_html: rawHtml,
    raw_text: '',
    description,
    transcript_source_url: transcriptSourceUrl,
    download_url: String(audioEnclosure?.url || '').trim(),
    ...(explicitUseSpeakerRecognition == null ? {} : { use_speaker_recognition: explicitUseSpeakerRecognition }),
    obsidian_inbox_dir: String(sourceContext.obsidianInboxDir || sourceContext.obsidian_inbox_dir || '00_Inbox').trim() || '00_Inbox',
    extra_tags: extraTags,
    route_to_transcript: routeToTranscript,
    is_new_since_last_poll: Boolean(sourceContext.is_new_since_last_poll),
    source_gate_status: String(sourceContext.source_gate_status || '').trim(),
    source_item_count: Number(sourceContext.source_item_count || 0) || 0,
    source_new_item_count: Number(sourceContext.source_new_item_count || 0) || 0,
    source_sample_titles: Array.isArray(sourceContext.source_sample_titles) ? sourceContext.source_sample_titles.slice(0, 5) : [],
    source_new_titles: Array.isArray(sourceContext.source_new_titles) ? sourceContext.source_new_titles.slice(0, 5) : [],
    source_state_path: String(sourceContext.source_state_path || '').trim(),
    source_key: String(sourceContext.source_key || '').trim(),
    source_processing_status: String(sourceContext.source_processing_status || '').trim(),
    source_previous_latest_seen_guid: String(sourceContext.source_previous_latest_seen_guid || '').trim(),
    source_previous_latest_seen_link: String(sourceContext.source_previous_latest_seen_link || '').trim(),
    source_previous_latest_seen_published_at: String(sourceContext.source_previous_latest_seen_published_at || '').trim(),
    source_previous_latest_seen_title: String(sourceContext.source_previous_latest_seen_title || '').trim(),
    source_previous_latest_processed_guid: String(sourceContext.source_previous_latest_processed_guid || '').trim(),
    source_previous_latest_processed_link: String(sourceContext.source_previous_latest_processed_link || '').trim(),
    source_previous_latest_processed_published_at: String(sourceContext.source_previous_latest_processed_published_at || '').trim(),
    source_previous_latest_processed_title: String(sourceContext.source_previous_latest_processed_title || '').trim(),
    source_pending_latest_guid: String(sourceContext.source_pending_latest_guid || '').trim(),
    source_pending_latest_link: String(sourceContext.source_pending_latest_link || '').trim(),
    source_pending_latest_published_at: String(sourceContext.source_pending_latest_published_at || '').trim(),
    source_pending_latest_title: String(sourceContext.source_pending_latest_title || '').trim(),
    source_previous_latest_guid: String(sourceContext.source_previous_latest_guid || '').trim(),
    source_previous_latest_link: String(sourceContext.source_previous_latest_link || '').trim(),
    source_previous_latest_published_at: String(sourceContext.source_previous_latest_published_at || '').trim(),
    source_previous_latest_title: String(sourceContext.source_previous_latest_title || '').trim(),
    source_current_latest_guid: String(sourceContext.source_current_latest_guid || '').trim(),
    source_current_latest_link: String(sourceContext.source_current_latest_link || '').trim(),
    source_current_latest_published_at: String(sourceContext.source_current_latest_published_at || '').trim(),
    source_current_latest_title: String(sourceContext.source_current_latest_title || '').trim(),
    last_seen_recorded_at: String(sourceContext.last_seen_recorded_at || '').trim(),
    ...(transcriptPollIntervalMs > 0 ? { poll_interval_ms: transcriptPollIntervalMs } : {}),
    ...(transcriptMaxPolls > 0 ? { max_polls: transcriptMaxPolls } : {}),
    upstream_task_id: '',
    upstream_view_token: '',
    upstream_summary: '',
    original_item: $json
  }
};

const inputItems = $input.all();
const now = new Date();
const pad = (value) => String(value).padStart(2, '0');
const year = now.getFullYear();
const month = pad(now.getMonth() + 1);
const day = pad(now.getDate());
const hour = pad(now.getHours());
const minute = pad(now.getMinutes());
const second = pad(now.getSeconds());
const tzOffsetMinutes = -now.getTimezoneOffset();
const tzSign = tzOffsetMinutes >= 0 ? '+' : '-';
const tzHours = pad(Math.floor(Math.abs(tzOffsetMinutes) / 60));
const tzMinutes = pad(Math.abs(tzOffsetMinutes) % 60);
const isoLike = `${year}-${month}-${day}T${hour}-${minute}-${second}${tzSign}${tzHours}-${tzMinutes}`;

const safeString = (value) => {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
};

const asBooleanOrNull = (value) => {
  if (typeof value === 'boolean') {
    return value;
  }
  return null;
};

const numberOrZero = (value) => {
  const numericValue = Number(value || 0);
  return Number.isFinite(numericValue) ? numericValue : 0;
};

const arrayOfStrings = (value) => Array.isArray(value)
  ? value.map((entry) => safeString(entry)).filter(Boolean)
  : [];

const tokenUsageFields = [
  'prompt_tokens',
  'completion_tokens',
  'total_tokens',
  'cached_prompt_tokens',
  'prompt_cache_hit_tokens',
  'prompt_cache_miss_tokens',
  'reasoning_tokens'
];

const plainObjectOrNull = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : null;

const usageIntOrNull = (value) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue) || numericValue < 0) {
    return null;
  }
  return Math.round(numericValue);
};

const createLlmUsageTotals = () => ({
  calls: 0,
  usage_missing: 0,
  prompt_tokens: 0,
  completion_tokens: 0,
  total_tokens: 0,
  cached_prompt_tokens: 0,
  prompt_cache_hit_tokens: 0,
  prompt_cache_miss_tokens: 0,
  reasoning_tokens: 0
});

const normalizeLlmUsage = (value) => {
  const source = plainObjectOrNull(value);
  if (!source) {
    return null;
  }
  const hasNormalizedShape = Object.prototype.hasOwnProperty.call(source, 'usage_available')
    || Object.prototype.hasOwnProperty.call(source, 'cached_prompt_tokens')
    || Object.prototype.hasOwnProperty.call(source, 'prompt_cache_hit_tokens');
  const rawUsage = plainObjectOrNull(source.raw_usage) || (hasNormalizedShape ? null : source);

  const promptTokens = usageIntOrNull(source.prompt_tokens ?? source.input_tokens ?? rawUsage?.prompt_tokens ?? rawUsage?.input_tokens);
  const completionTokens = usageIntOrNull(source.completion_tokens ?? source.output_tokens ?? rawUsage?.completion_tokens ?? rawUsage?.output_tokens);
  let totalTokens = usageIntOrNull(source.total_tokens ?? rawUsage?.total_tokens);
  if (totalTokens === null && promptTokens !== null && completionTokens !== null) {
    totalTokens = promptTokens + completionTokens;
  }
  const cachedPromptTokens = usageIntOrNull(
    source.cached_prompt_tokens
    ?? source.cached_input_tokens
    ?? rawUsage?.prompt_tokens_details?.cached_tokens
    ?? rawUsage?.input_tokens_details?.cached_tokens
    ?? rawUsage?.prompt_cache_hit_tokens
    ?? rawUsage?.cache_read_input_tokens
  );
  const promptCacheHitTokens = usageIntOrNull(
    source.prompt_cache_hit_tokens
    ?? source.cache_read_input_tokens
    ?? rawUsage?.prompt_cache_hit_tokens
    ?? rawUsage?.cache_read_input_tokens
    ?? cachedPromptTokens
  );
  let promptCacheMissTokens = usageIntOrNull(source.prompt_cache_miss_tokens ?? rawUsage?.prompt_cache_miss_tokens);
  if (promptCacheMissTokens === null && promptTokens !== null && promptCacheHitTokens !== null) {
    promptCacheMissTokens = Math.max(0, promptTokens - promptCacheHitTokens);
  }
  const reasoningTokens = usageIntOrNull(
    source.reasoning_tokens
    ?? rawUsage?.completion_tokens_details?.reasoning_tokens
    ?? rawUsage?.output_tokens_details?.reasoning_tokens
  );
  const hasAnyTokenValue = [
    promptTokens,
    completionTokens,
    totalTokens,
    cachedPromptTokens,
    promptCacheHitTokens,
    promptCacheMissTokens,
    reasoningTokens
  ].some((entry) => entry !== null);
  const usageAvailable = typeof source.usage_available === 'boolean'
    ? source.usage_available
    : hasAnyTokenValue;
  if (!usageAvailable && !Object.prototype.hasOwnProperty.call(source, 'usage_available')) {
    return null;
  }

  return {
    model_profile: safeString(source.model_profile || ''),
    provider: safeString(source.provider || ''),
    model: safeString(source.model || ''),
    prompt_version: safeString(source.prompt_version || ''),
    usage_available: usageAvailable,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: totalTokens,
    cached_prompt_tokens: cachedPromptTokens,
    prompt_cache_hit_tokens: promptCacheHitTokens,
    prompt_cache_miss_tokens: promptCacheMissTokens,
    reasoning_tokens: reasoningTokens,
    raw_usage: rawUsage ? JSON.parse(JSON.stringify(rawUsage)) : null
  };
};

const addLlmUsageTotals = (totals, usage, llmRan = false) => {
  const normalized = normalizeLlmUsage(usage);
  if (normalized?.usage_available) {
    totals.calls += 1;
    for (const field of tokenUsageFields) {
      const value = usageIntOrNull(normalized[field]);
      if (value !== null) {
        totals[field] += value;
      }
    }
  } else if (llmRan) {
    totals.usage_missing += 1;
  }
  return totals;
};

const buildLlmUsageTotalsFromItems = (items = []) => {
  const totals = createLlmUsageTotals();
  for (const item of Array.isArray(items) ? items : []) {
    addLlmUsageTotals(totals, item?.llm_usage, Boolean(item?.llm_ran));
  }
  return totals;
};

const mergeLlmUsageTotals = (...groups) => {
  const totals = createLlmUsageTotals();
  for (const group of groups) {
    const usage = plainObjectOrNull(group);
    if (!usage) {
      continue;
    }
    totals.calls += numberOrZero(usage.calls);
    totals.usage_missing += numberOrZero(usage.usage_missing);
    for (const field of tokenUsageFields) {
      totals[field] += numberOrZero(usage[field]);
    }
  }
  return totals;
};

const flattenLlmUsageFields = (usage) => ({
  llm_prompt_tokens: usageIntOrNull(usage?.prompt_tokens),
  llm_completion_tokens: usageIntOrNull(usage?.completion_tokens),
  llm_total_tokens: usageIntOrNull(usage?.total_tokens),
  llm_cached_prompt_tokens: usageIntOrNull(usage?.cached_prompt_tokens),
  llm_prompt_cache_hit_tokens: usageIntOrNull(usage?.prompt_cache_hit_tokens),
  llm_prompt_cache_miss_tokens: usageIntOrNull(usage?.prompt_cache_miss_tokens),
  llm_reasoning_tokens: usageIntOrNull(usage?.reasoning_tokens)
});

const flattenLlmUsageTotals = (usage) => ({
  llm_calls: numberOrZero(usage?.calls),
  llm_usage_missing: numberOrZero(usage?.usage_missing),
  ...flattenLlmUsageFields(usage)
});

const getExecutionId = () => {
  try {
    if (typeof $execution !== 'undefined') {
      return safeString($execution.id || $execution.executionId || '');
    }
  } catch {}
  return '';
};

const getRunStartedAt = () => {
  try {
    if (typeof $execution !== 'undefined') {
      const value = safeString($execution.startedAt || $execution.startTime || '');
      if (value) return value;
    }
  } catch {}
  try {
    const value = $('Schedule Trigger').first()?.json?.timestamp;
    if (value) return value;
  } catch {}
  try {
    const value = $("When clicking 'Execute workflow'").first()?.json?.startedAt;
    if (value) return value;
  } catch {}
  try {
    const value = $('When Executed by Another Workflow').first()?.json?.triggered_at;
    if (value) return value;
  } catch {}
  return '';
};

const toSafeDate = (value, fallback = now) => {
  const parsed = new Date(value || '');
  if (!Number.isNaN(parsed.getTime())) {
    return parsed;
  }
  const fallbackDate = fallback instanceof Date ? fallback : new Date(fallback);
  return Number.isNaN(fallbackDate.getTime()) ? now : fallbackDate;
};

const toIsoLike = (date) => {
  const safeDate = toSafeDate(date, now);
  const localYear = safeDate.getFullYear();
  const localMonth = pad(safeDate.getMonth() + 1);
  const localDay = pad(safeDate.getDate());
  const localHour = pad(safeDate.getHours());
  const localMinute = pad(safeDate.getMinutes());
  const localSecond = pad(safeDate.getSeconds());
  const offsetMinutes = -safeDate.getTimezoneOffset();
  const offsetSign = offsetMinutes >= 0 ? '+' : '-';
  const offsetHours = pad(Math.floor(Math.abs(offsetMinutes) / 60));
  const offsetMinutePart = pad(Math.abs(offsetMinutes) % 60);
  return `${localYear}-${localMonth}-${localDay}T${localHour}-${localMinute}-${localSecond}${offsetSign}${offsetHours}-${offsetMinutePart}`;
};

const shouldRouteToTranscript = ({ routeToTranscript = null, sourceType = '', feedUrl = '' } = {}) => {
  if (typeof routeToTranscript === 'boolean') {
    return routeToTranscript;
  }
  const normalizedSourceType = safeString(sourceType).toLowerCase();
  if (['podcast', 'audio', 'podcast_rss'].includes(normalizedSourceType)) {
    return true;
  }
  return /https?:\/\/(?:www\.)?xiaoyuzhoufm\.com\//i.test(safeString(feedUrl));
};

const createSourceEntry = ({ feedUrl = '', sourceName = '', sourceType = '', routeToTranscript = null } = {}) => {
  const transcriptRequested = shouldRouteToTranscript({ routeToTranscript, sourceType, feedUrl });
  return {
    feed_url: safeString(feedUrl),
    source_name: safeString(sourceName),
    source_type: safeString(sourceType),
    rss_status: 'success',
    rss_error: '',
    transcript_status: transcriptRequested ? 'pending' : 'not_requested',
    transcript_error: '',
    is_new_since_last_poll: false,
    source_gate_status: 'not_checked',
    source_processing_status: '',
    last_seen_state_path: '',
    last_seen_recorded_at: '',
    previous_latest_guid: '',
    previous_latest_link: '',
    previous_latest_published_at: '',
    previous_latest_title: '',
    current_latest_guid: '',
    current_latest_link: '',
    current_latest_published_at: '',
    current_latest_title: '',
    item_count: 0,
    new_item_count: 0,
    wrote_count: 0,
    wrote_paths: [],
    qdrant_commit_count: 0,
    llm_usage: createLlmUsageTotals(),
    dedupe_actions: [],
    vault_write_statuses: [],
    sample_titles: [],
    new_titles: [],
    items: []
  };
};

const getSourceKey = ({ feedUrl = '', sourceName = '', sourceType = '' } = {}) => {
  const normalizedFeedUrl = safeString(feedUrl);
  const normalizedSourceName = safeString(sourceName);
  const normalizedSourceType = safeString(sourceType);
  if (normalizedFeedUrl) {
    return normalizedFeedUrl;
  }
  if (normalizedSourceName || normalizedSourceType) {
    return `${normalizedSourceName}::${normalizedSourceType}`;
  }
  return '';
};

const readSourceMetadata = (data = {}) => {
  const originalItem = data.original_item && typeof data.original_item === 'object' ? data.original_item : {};
  return {
    feedUrl: safeString(data.feed_url || data.feedUrl || originalItem.feed_url || originalItem.feedUrl || ''),
    sourceName: safeString(data.source_name || data.sourceName || originalItem.source_name || originalItem.sourceName || ''),
    sourceType: safeString(data.source_type || data.sourceType || originalItem.source_type || originalItem.sourceType || ''),
    routeToTranscript: (() => {
      const topLevel = asBooleanOrNull(data.route_to_transcript ?? data.routeToTranscript);
      if (topLevel !== null) {
        return topLevel;
      }
      return asBooleanOrNull(originalItem.route_to_transcript ?? originalItem.routeToTranscript);
    })(),
    isNewSinceLastPoll: (() => {
      const topLevel = asBooleanOrNull(data.is_new_since_last_poll);
      if (topLevel !== null) {
        return topLevel;
      }
      return asBooleanOrNull(originalItem.is_new_since_last_poll);
    })(),
    sourceGateStatus: safeString(data.source_gate_status || originalItem.source_gate_status || ''),
    sourceItemCount: numberOrZero(data.source_item_count || originalItem.source_item_count || 0),
    sourceNewItemCount: numberOrZero(data.source_new_item_count || originalItem.source_new_item_count || 0),
    sampleTitles: arrayOfStrings(data.source_sample_titles || originalItem.source_sample_titles || []),
    newTitles: arrayOfStrings(data.source_new_titles || originalItem.source_new_titles || []),
    sourceStatePath: safeString(data.source_state_path || originalItem.source_state_path || ''),
    sourceProcessingStatus: safeString(data.source_processing_status || originalItem.source_processing_status || ''),
    lastSeenRecordedAt: safeString(data.last_seen_recorded_at || originalItem.last_seen_recorded_at || ''),
    previousLatestSeenGuid: safeString(data.source_previous_latest_seen_guid || originalItem.source_previous_latest_seen_guid || ''),
    previousLatestSeenLink: safeString(data.source_previous_latest_seen_link || originalItem.source_previous_latest_seen_link || ''),
    previousLatestSeenPublishedAt: safeString(data.source_previous_latest_seen_published_at || originalItem.source_previous_latest_seen_published_at || ''),
    previousLatestSeenTitle: safeString(data.source_previous_latest_seen_title || originalItem.source_previous_latest_seen_title || ''),
    previousLatestProcessedGuid: safeString(data.source_previous_latest_processed_guid || originalItem.source_previous_latest_processed_guid || ''),
    previousLatestProcessedLink: safeString(data.source_previous_latest_processed_link || originalItem.source_previous_latest_processed_link || ''),
    previousLatestProcessedPublishedAt: safeString(data.source_previous_latest_processed_published_at || originalItem.source_previous_latest_processed_published_at || ''),
    previousLatestProcessedTitle: safeString(data.source_previous_latest_processed_title || originalItem.source_previous_latest_processed_title || ''),
    pendingLatestGuid: safeString(data.source_pending_latest_guid || originalItem.source_pending_latest_guid || ''),
    pendingLatestLink: safeString(data.source_pending_latest_link || originalItem.source_pending_latest_link || ''),
    pendingLatestPublishedAt: safeString(data.source_pending_latest_published_at || originalItem.source_pending_latest_published_at || ''),
    pendingLatestTitle: safeString(data.source_pending_latest_title || originalItem.source_pending_latest_title || ''),
    previousLatestGuid: safeString(data.source_previous_latest_guid || originalItem.source_previous_latest_guid || ''),
    previousLatestLink: safeString(data.source_previous_latest_link || originalItem.source_previous_latest_link || ''),
    previousLatestPublishedAt: safeString(data.source_previous_latest_published_at || originalItem.source_previous_latest_published_at || ''),
    previousLatestTitle: safeString(data.source_previous_latest_title || originalItem.source_previous_latest_title || ''),
    currentLatestGuid: safeString(data.source_current_latest_guid || originalItem.source_current_latest_guid || ''),
    currentLatestLink: safeString(data.source_current_latest_link || originalItem.source_current_latest_link || ''),
    currentLatestPublishedAt: safeString(data.source_current_latest_published_at || originalItem.source_current_latest_published_at || ''),
    currentLatestTitle: safeString(data.source_current_latest_title || originalItem.source_current_latest_title || '')
  };
};


const objectOrNull = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : null;

const chooseString = (...values) => {
  for (const value of values) {
    const text = safeString(value);
    if (text) {
      return text;
    }
  }
  return '';
};

const roundOrNull = (value, digits = 4) => {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) {
    return null;
  }
  return Number(numericValue.toFixed(digits));
};

const clonePlainObject = (value) => {
  const objectValue = objectOrNull(value);
  if (!objectValue) {
    return null;
  }
  return JSON.parse(JSON.stringify(objectValue));
};

const readItemUrl = (data = {}, originalItem = {}, metadata = {}) => chooseString(
  data.canonical_url,
  data.canonicalUrl,
  data.link,
  data.url,
  originalItem.canonical_url,
  originalItem.canonicalUrl,
  originalItem.link,
  originalItem.url,
  metadata.currentLatestLink
);

const readItemTitle = (data = {}, originalItem = {}, metadata = {}) => chooseString(
  data.title,
  originalItem.title,
  data.current_latest_title,
  metadata.currentLatestTitle
);

const readItemPublishedAt = (data = {}, originalItem = {}, metadata = {}) => chooseString(
  data.published_at,
  data.publishedAt,
  data.isoDate,
  data.pubDate,
  originalItem.published_at,
  originalItem.publishedAt,
  originalItem.isoDate,
  originalItem.pubDate,
  metadata.currentLatestPublishedAt
);

const readItemId = (data = {}, originalItem = {}, url = '', title = '') => chooseString(
  data.item_id,
  data.itemId,
  originalItem.item_id,
  originalItem.itemId,
  data.original_id,
  data.guid,
  data.id,
  originalItem.guid,
  originalItem.id,
  url,
  title
);

const inferAuditOutcome = (data = {}, hasScore = false) => {
  const stage = safeString(data.stage || '');
  const errorText = safeString(data.error || data.error_message || '');
  const dedupeAction = safeString(data.dedupe_action || data.dedupeAction || '');
  const vaultStatus = safeString(data.vault_write_status || data.vault_write || '');
  const qdrantOperation = safeString(data.qdrant_operation || '');
  const shouldWriteToVault = typeof data.should_write_to_vault === 'boolean' ? data.should_write_to_vault : null;
  const shouldContinueToProcessing = typeof data.should_continue_to_processing === 'boolean' ? data.should_continue_to_processing : null;
  const shouldContinueToLlm = typeof data.should_continue_to_llm === 'boolean' ? data.should_continue_to_llm : null;

  if (errorText) {
    return {
      audit_status: 'failed',
      audit_reason: stage ? `${stage}_error` : 'error',
      audit_detail: errorText
    };
  }
  if (vaultStatus === 'written') {
    return {
      audit_status: 'written',
      audit_reason: 'vault_written',
      audit_detail: 'Vault writer produced an Obsidian note.'
    };
  }
  if (vaultStatus === 'error') {
    return {
      audit_status: 'failed',
      audit_reason: 'vault_write_error',
      audit_detail: 'Vault writer returned error.'
    };
  }
  if (dedupeAction === 'silent') {
    return {
      audit_status: 'skipped',
      audit_reason: 'silent_dedupe',
      audit_detail: 'Qdrant gate treated this item as duplicate or already covered.'
    };
  }
  if (shouldContinueToProcessing === false) {
    return {
      audit_status: 'skipped',
      audit_reason: 'source_last_seen_gate',
      audit_detail: 'Source last-seen gate did not continue this item to downstream processing.'
    };
  }
  if (shouldContinueToLlm === false) {
    return {
      audit_status: 'skipped',
      audit_reason: 'llm_not_requested',
      audit_detail: 'The item stopped before the LLM scoring step.'
    };
  }
  if (hasScore && shouldWriteToVault === false) {
    return {
      audit_status: 'skipped',
      audit_reason: 'action_policy_skipped',
      audit_detail: 'Action policy decided not to write this scored item to Obsidian.'
    };
  }
  if (hasScore) {
    return {
      audit_status: 'scored',
      audit_reason: 'scored_without_vault_write_record',
      audit_detail: 'The item has LLM scores but no final written vault path in this summary.'
    };
  }
  if (qdrantOperation === 'skipped') {
    return {
      audit_status: 'skipped',
      audit_reason: 'qdrant_skipped',
      audit_detail: 'The item did not proceed to Qdrant upsert.'
    };
  }
  return {
    audit_status: 'not_scored',
    audit_reason: 'score_not_available',
    audit_detail: 'No LLM score was present in the poll summary inputs.'
  };
};

const inferSkipLayer = (outcome = {}, data = {}, hasScore = false) => {
  const reason = safeString(outcome.audit_reason || '');
  const stage = safeString(data.stage || '');
  if (reason === 'source_last_seen_gate') {
    return 'source_last_seen_gate';
  }
  if (reason === 'silent_dedupe' || reason === 'llm_not_requested') {
    return 'qdrant_gate';
  }
  if (reason === 'action_policy_skipped') {
    return 'action_policy';
  }
  if (reason === 'vault_written' || reason === 'vault_write_error') {
    return 'vault_writer';
  }
  if (reason === 'qdrant_skipped') {
    return 'qdrant_commit';
  }
  if (reason.endsWith('_error')) {
    return stage || 'error';
  }
  if (hasScore) {
    return 'llm_scoring';
  }
  return 'pre_llm';
};

const buildAuditItem = (data = {}, metadata = {}) => {
  const originalItem = objectOrNull(data.original_item) || {};
  const title = readItemTitle(data, originalItem, metadata);
  const url = readItemUrl(data, originalItem, metadata);
  const publishedAt = readItemPublishedAt(data, originalItem, metadata);
  const itemId = readItemId(data, originalItem, url, title);
  if (!title && !url && !itemId) {
    return null;
  }

  const aiScore = clonePlainObject(data.ai_score);
  const scoreDimensions = clonePlainObject(data.score_dimensions);
  const llmUsage = normalizeLlmUsage(data.llm_usage || data.ai_meta?.usage || data.usage);
  const hasScore = Boolean(aiScore || scoreDimensions || data.score !== undefined || llmUsage);
  const outcome = inferAuditOutcome(data, hasScore);
  const skipLayer = inferSkipLayer(outcome, data, hasScore);
  const eventDelta = objectOrNull(data.event_delta) || {};
  const matchedPayload = objectOrNull(data.matched_payload) || {};
  const scoreScale = numberOrZero(data.score_scale || 100) || 100;

  return {
    audit_key: itemId || url || title,
    item_id: safeString(data.item_id || data.itemId || ''),
    original_id: safeString(data.original_id || originalItem.guid || originalItem.id || ''),
    title,
    url,
    published_at: publishedAt,
    author: chooseString(data.author, originalItem.author, originalItem.creator),
    source_gate_status: safeString(metadata.sourceGateStatus || data.source_gate_status || ''),
    stage: safeString(data.stage || ''),
    llm_ran: hasScore,
    skip_layer: skipLayer,
    audit_status: outcome.audit_status,
    audit_reason: outcome.audit_reason,
    audit_detail: outcome.audit_detail,
    dedupe_action: safeString(data.dedupe_action || data.dedupeAction || ''),
    notification_mode: safeString(data.notification_mode || ''),
    vault_write_status: safeString(data.vault_write_status || data.vault_write || ''),
    vault_path: safeString(data.vault_path || ''),
    qdrant_operation: safeString(data.qdrant_operation || ''),
    should_write_to_vault: typeof data.should_write_to_vault === 'boolean' ? data.should_write_to_vault : null,
    should_notify: typeof data.should_notify === 'boolean' ? data.should_notify : null,
    should_upsert_qdrant: typeof data.should_upsert_qdrant === 'boolean' ? data.should_upsert_qdrant : null,
    score: roundOrNull(data.score, 4),
    score_scale: scoreScale,
    keep_score: roundOrNull(aiScore?.keep_score, 0),
    notify_score: roundOrNull(aiScore?.notify_score, 0),
    reference_score: roundOrNull(aiScore?.reference_score, 0),
    action_score: roundOrNull(aiScore?.action_score, 0),
    confidence: roundOrNull(aiScore?.confidence, 4),
    decision_hint: safeString(aiScore?.decision_hint || ''),
    ai_score: aiScore,
    score_dimensions: scoreDimensions,
    llm_usage: llmUsage,
    ...flattenLlmUsageFields(llmUsage),
    category: safeString(data.category || ''),
    tags: arrayOfStrings(data.tags).slice(0, 20),
    summary: safeString(data.summary || ''),
    llm_reason: safeString(data.reason || ''),
    event_relation: safeString(eventDelta.relation || ''),
    delta_importance: roundOrNull(eventDelta.delta_importance, 0),
    matched_score: roundOrNull(data.matched_score, 4),
    matched_item_id: safeString(matchedPayload.item_id || ''),
    matched_title: safeString(matchedPayload.title || '')
  };
};

const mergeStringArrays = (...groups) => {
  const values = [];
  const seen = new Set();
  for (const group of groups) {
    for (const value of Array.isArray(group) ? group : []) {
      const text = safeString(value);
      if (text && !seen.has(text)) {
        seen.add(text);
        values.push(text);
      }
    }
  }
  return values;
};

const auditStatusRank = {
  failed: 60,
  written: 50,
  scored: 40,
  skipped: 30,
  not_scored: 20,
  seen: 10,
  '': 0
};

const mergeAuditItems = (left = {}, right = {}) => {
  const merged = { ...left, ...right };
  const preferString = (key) => {
    merged[key] = safeString(right[key]) || safeString(left[key]);
  };
  for (const key of [
    'audit_key',
    'item_id',
    'original_id',
    'title',
    'url',
    'published_at',
    'author',
    'source_gate_status',
    'stage',
    'skip_layer',
    'dedupe_action',
    'notification_mode',
    'vault_write_status',
    'vault_path',
    'qdrant_operation',
    'decision_hint',
    'category',
    'summary',
    'llm_reason',
    'event_relation',
    'matched_item_id',
    'matched_title'
  ]) {
    preferString(key);
  }
  const leftStatus = safeString(left.audit_status);
  const rightStatus = safeString(right.audit_status);
  const chosenStatusSource = (auditStatusRank[rightStatus] || 0) >= (auditStatusRank[leftStatus] || 0) ? right : left;
  merged.audit_status = safeString(chosenStatusSource.audit_status || merged.audit_status);
  merged.audit_reason = safeString(chosenStatusSource.audit_reason || merged.audit_reason);
  merged.audit_detail = safeString(chosenStatusSource.audit_detail || merged.audit_detail);
  merged.skip_layer = safeString(chosenStatusSource.skip_layer || merged.skip_layer);
  merged.llm_ran = Boolean(left.llm_ran || right.llm_ran);
  const mergedLlmUsage = normalizeLlmUsage(right.llm_usage) || normalizeLlmUsage(left.llm_usage);
  merged.llm_usage = mergedLlmUsage;
  Object.assign(merged, flattenLlmUsageFields(mergedLlmUsage));
  merged.tags = mergeStringArrays(left.tags, right.tags).slice(0, 20);
  merged.ai_score = clonePlainObject(right.ai_score) || clonePlainObject(left.ai_score);
  merged.score_dimensions = clonePlainObject(right.score_dimensions) || clonePlainObject(left.score_dimensions);
  return merged;
};

const upsertAuditItem = (entry, auditItem) => {
  if (!auditItem) {
    return;
  }
  const key = safeString(auditItem.audit_key || auditItem.item_id || auditItem.url || auditItem.title);
  if (!key) {
    return;
  }
  const existingIndex = entry.items.findIndex((item) => safeString(item.audit_key || item.item_id || item.url || item.title) === key);
  if (existingIndex >= 0) {
    entry.items[existingIndex] = mergeAuditItems(entry.items[existingIndex], auditItem);
  } else {
    entry.items.push(auditItem);
  }
};

const items = inputItems;

const pollBySource = new Map();
const sourceAliasToKey = new Map();

const getSourceAlias = ({ sourceName = '', sourceType = '' } = {}) => {
  const normalizedSourceName = safeString(sourceName);
  const normalizedSourceType = safeString(sourceType);
  return normalizedSourceName || normalizedSourceType
    ? `${normalizedSourceName}::${normalizedSourceType}`
    : '';
};

const rememberSourceAlias = (source = {}, sourceKey = '') => {
  const alias = getSourceAlias({
    sourceName: source.sourceName || source.source_name,
    sourceType: source.sourceType || source.source_type
  });
  if (sourceKey && alias && !sourceAliasToKey.has(alias)) {
    sourceAliasToKey.set(alias, sourceKey);
  }
};

const resolveSourceKey = (metadata = {}) => {
  const directKey = getSourceKey(metadata);
  if (directKey && pollBySource.has(directKey)) {
    return directKey;
  }
  if (safeString(metadata.feedUrl)) {
    return directKey;
  }
  const alias = getSourceAlias(metadata);
  return sourceAliasToKey.get(alias) || directKey;
};

const hydrateSourceMetadata = (metadata = {}, sourceKey = '') => {
  const known = sourceKey ? pollBySource.get(sourceKey) : null;
  if (!known) {
    return metadata;
  }
  return {
    ...metadata,
    feedUrl: metadata.feedUrl || known.feed_url || '',
    sourceName: metadata.sourceName || known.source_name || '',
    sourceType: metadata.sourceType || known.source_type || ''
  };
};

const applySourceMetadataToEntry = (entry, metadata = {}) => {
  if (metadata.sourceItemCount >= 0) {
    entry.item_count = Math.max(entry.item_count, metadata.sourceItemCount);
  }
  if (metadata.sourceNewItemCount >= 0) {
    entry.new_item_count = Math.max(entry.new_item_count, metadata.sourceNewItemCount);
  }
  if (metadata.isNewSinceLastPoll !== null) {
    entry.is_new_since_last_poll = metadata.isNewSinceLastPoll;
  }
  if (metadata.sourceGateStatus) {
    entry.source_gate_status = metadata.sourceGateStatus;
  }
  if (metadata.sourceStatePath) {
    entry.last_seen_state_path = metadata.sourceStatePath;
  }
  if (metadata.sourceProcessingStatus) {
    entry.source_processing_status = metadata.sourceProcessingStatus;
  }
  if (metadata.lastSeenRecordedAt) {
    entry.last_seen_recorded_at = metadata.lastSeenRecordedAt;
  }
  entry.previous_latest_guid = metadata.previousLatestGuid || entry.previous_latest_guid;
  entry.previous_latest_link = metadata.previousLatestLink || entry.previous_latest_link;
  entry.previous_latest_published_at = metadata.previousLatestPublishedAt || entry.previous_latest_published_at;
  entry.previous_latest_title = metadata.previousLatestTitle || entry.previous_latest_title;
  entry.current_latest_guid = metadata.currentLatestGuid || entry.current_latest_guid;
  entry.current_latest_link = metadata.currentLatestLink || entry.current_latest_link;
  entry.current_latest_published_at = metadata.currentLatestPublishedAt || entry.current_latest_published_at;
  entry.current_latest_title = metadata.currentLatestTitle || entry.current_latest_title;
  if (metadata.sampleTitles.length) {
    entry.sample_titles = metadata.sampleTitles.slice(0, 5);
  }
  if (metadata.newTitles.length) {
    entry.new_titles = metadata.newTitles.slice(0, 5);
  }
  return entry;
};

try {
  for (const sourceItem of $('Feed Sources').all()) {
    const sourceData = sourceItem.json && typeof sourceItem.json === 'object' ? sourceItem.json : {};
    const sourceKey = getSourceKey({
      feedUrl: sourceData.feedUrl,
      sourceName: sourceData.sourceName,
      sourceType: sourceData.sourceType
    });
    if (!sourceKey) {
      continue;
    }
    pollBySource.set(
      sourceKey,
      createSourceEntry({
        feedUrl: sourceData.feedUrl,
        sourceName: sourceData.sourceName,
        sourceType: sourceData.sourceType,
        routeToTranscript: sourceData.routeToTranscript
      })
    );
    rememberSourceAlias(sourceData, sourceKey);
  }
} catch {}

try {
  for (const gateItem of $('07 Common Source Last Seen Gate').all()) {
    const gateData = gateItem.json && typeof gateItem.json === 'object' ? gateItem.json : {};
    const rawMetadata = readSourceMetadata(gateData);
    const sourceKey = resolveSourceKey(rawMetadata);
    if (!sourceKey) {
      continue;
    }
    const metadata = hydrateSourceMetadata(rawMetadata, sourceKey);
    const entry = pollBySource.get(sourceKey) || createSourceEntry(metadata);
    applySourceMetadataToEntry(entry, metadata);
    upsertAuditItem(entry, buildAuditItem(gateData, metadata));
    pollBySource.set(sourceKey, entry);
  }
} catch {}

for (const item of items) {
  const data = item.json && typeof item.json === 'object' ? item.json : {};
  const rawMetadata = readSourceMetadata(data);
  const sourceKey = resolveSourceKey(rawMetadata);
  if (!sourceKey) {
    continue;
  }
  const metadata = hydrateSourceMetadata(rawMetadata, sourceKey);
  const entry = pollBySource.get(sourceKey) || createSourceEntry(metadata);
  const auditItem = buildAuditItem(data, metadata);
  upsertAuditItem(entry, auditItem);

  applySourceMetadataToEntry(entry, metadata);

  if (safeString(data.stage) === 'rss_read') {
    entry.rss_status = 'error';
    entry.rss_error = safeString(data.error || 'unknown RSS read error') || 'unknown RSS read error';
    if (entry.transcript_status === 'pending') {
      entry.transcript_status = 'not_requested';
    }
    pollBySource.set(sourceKey, entry);
    continue;
  }

  if (safeString(data.stage) === 'transcript_ingest') {
    entry.transcript_status = 'error';
    entry.transcript_error = safeString(data.error || 'unknown transcript ingest error') || 'unknown transcript ingest error';
    pollBySource.set(sourceKey, entry);
    continue;
  }

  if (safeString(data.stage) === 'normalize_text_object') {
    const normalizeError = safeString(data.error || 'unknown normalize text object error') || 'unknown normalize text object error';
    const normalizeMessage = `Normalize text object failed: ${normalizeError}`;
    if (shouldRouteToTranscript({
      routeToTranscript: metadata.routeToTranscript,
      sourceType: metadata.sourceType || data.source_type,
      feedUrl: metadata.feedUrl || data.feed_url
    })) {
      entry.transcript_status = 'error';
      entry.transcript_error = normalizeMessage;
    }
    if (!entry.vault_write_statuses.includes('error')) {
      entry.vault_write_statuses.push('error');
    }
    pollBySource.set(sourceKey, entry);
    continue;
  }

  if (safeString(data.stage) === 'source_last_seen_gate' && !data.should_continue_to_processing) {
    if (entry.new_item_count === 0 && entry.transcript_status === 'pending') {
      entry.transcript_status = 'not_requested';
    }
    pollBySource.set(sourceKey, entry);
    continue;
  }

  const title = safeString(data.title);
  if (title && entry.sample_titles.length < 5 && !entry.sample_titles.includes(title)) {
    entry.sample_titles.push(title);
  }
  const shouldMarkTranscriptSuccess = Boolean(
    shouldRouteToTranscript({
      routeToTranscript: metadata.routeToTranscript,
      sourceType: metadata.sourceType || data.source_type,
      feedUrl: metadata.feedUrl || data.feed_url
    }) && data.item_id
  );
  if (shouldMarkTranscriptSuccess && entry.transcript_status === 'pending') {
    entry.transcript_status = 'success';
  }
  const dedupeAction = safeString(data.dedupe_action || data.dedupeAction || '');
  if (dedupeAction && !entry.dedupe_actions.includes(dedupeAction)) {
    entry.dedupe_actions.push(dedupeAction);
  }
  const vaultStatus = safeString(data.vault_write_status || data.vault_write || '');
  if (vaultStatus && !entry.vault_write_statuses.includes(vaultStatus)) {
    entry.vault_write_statuses.push(vaultStatus);
  }
  const vaultPath = safeString(data.vault_path || '');
  if (vaultStatus === 'written' && vaultPath) {
    entry.wrote_count += 1;
    if (!entry.wrote_paths.includes(vaultPath)) {
      entry.wrote_paths.push(vaultPath);
    }
  }
  const qdrantOp = safeString(data.qdrant_operation || '');
  if (qdrantOp === 'written' || qdrantOp === 'upserted' || qdrantOp === 'pending') {
    entry.qdrant_commit_count += 1;
  }
  pollBySource.set(sourceKey, entry);
}

