    items_seen: mergedSources.reduce((sum, entry) => sum + numberOrZero(entry.item_count), 0),
    items_selected_for_processing: mergedSources.reduce((sum, entry) => sum + numberOrZero(entry.new_item_count), 0),
    items_written: mergedSources.reduce((sum, entry) => sum + numberOrZero(entry.wrote_count), 0),
    llm_usage: summaryLlmUsage,
    ...flattenLlmUsageTotals(summaryLlmUsage)
  };
};

const mergeSummaries = (previous, current) => {
  if (!previous || typeof previous !== 'object' || !Array.isArray(previous.sources)) {
    return current;
  }
  const sourceMap = new Map();
  const summaryAliasToKey = new Map();
  const rememberSummaryAlias = (source = {}, sourceKey = '') => {
    const alias = getSourceAlias({ sourceName: source.source_name, sourceType: source.source_type });
    if (sourceKey && alias && !summaryAliasToKey.has(alias)) {
      summaryAliasToKey.set(alias, sourceKey);
    }
  };
  const resolveSummarySourceKey = (source = {}) => {
    const directKey = getSourceKey({ feedUrl: source.feed_url, sourceName: source.source_name, sourceType: source.source_type });
    if (safeString(source.feed_url)) {
      return directKey;
    }
    const alias = getSourceAlias({ sourceName: source.source_name, sourceType: source.source_type });
    return summaryAliasToKey.get(alias) || directKey;
  };
  for (const source of previous.sources) {
    const sourceKey = getSourceKey({ feedUrl: source.feed_url, sourceName: source.source_name, sourceType: source.source_type });
    if (sourceKey) {
      sourceMap.set(sourceKey, source);
      rememberSummaryAlias(source, sourceKey);
    }
  }
  for (const source of current.sources) {
    const sourceKey = resolveSummarySourceKey(source);
    if (!sourceKey) continue;
    const mergedSource = mergeSourceEntries(sourceMap.get(sourceKey), source);
    sourceMap.set(sourceKey, mergedSource);
    rememberSummaryAlias(mergedSource, sourceKey);
  }
  const merged = {
    ...previous,
    ...current,
    run_started_at: previous.run_started_at || current.run_started_at,
    run_finished_at: current.run_finished_at,
    execution_id: current.execution_id || previous.execution_id || '',
    sources: Array.from(sourceMap.values())
  };
  return recomputeSummaryTotals(merged);
};

