const normalizeLatestForFinalize = (value) => {
  if (!value || typeof value !== 'object') {
    return null;
  }
  return {
    guid: safeString(value.guid || value.id || ''),
    link: safeString(value.link || value.canonical_url || ''),
    published_at: safeString(value.published_at || value.isoDate || value.pubDate || ''),
    title: safeString(value.title || '')
  };
};

const latestMatchesForFinalize = (left, right) => {
  const a = normalizeLatestForFinalize(left);
  const b = normalizeLatestForFinalize(right);
  if (!a || !b) {
    return false;
  }
  if (a.guid && b.guid && a.guid === b.guid) {
    return true;
  }
  if (a.link && b.link && a.link === b.link) {
    return true;
  }
  if (a.published_at && b.published_at && a.published_at === b.published_at) {
    if (a.title && b.title) {
      return a.title === b.title;
    }
    return true;
  }
  return false;
};

const latestFromSourceEntry = (source = {}) => ({
  guid: safeString(source.current_latest_guid || ''),
  link: safeString(source.current_latest_link || ''),
  published_at: safeString(source.current_latest_published_at || ''),
  title: safeString(source.current_latest_title || '')
});

const auditItemMatchesLatest = (item = {}, latest = {}) => {
  if (!latest || !Object.values(latest).some(Boolean)) {
    return false;
  }
  if (latest.guid && [item.item_id, item.original_id, item.audit_key, item.url].some((value) => safeString(value) === latest.guid)) {
    return true;
  }
  if (latest.link && [item.url, item.audit_key, item.item_id, item.original_id].some((value) => safeString(value) === latest.link)) {
    return true;
  }
  if (latest.published_at && safeString(item.published_at) === latest.published_at) {
    return !latest.title || !safeString(item.title) || safeString(item.title) === latest.title;
  }
  return Boolean(latest.title && safeString(item.title) === latest.title);
};

const isTerminalAuditItem = (item = {}) => {
  const status = safeString(item.audit_status || '');
  const reason = safeString(item.audit_reason || '');
  const vaultStatus = safeString(item.vault_write_status || '');
  const dedupeAction = safeString(item.dedupe_action || '');
  if (status === 'failed') {
    return false;
  }
  if (status === 'written' || vaultStatus === 'written') {
    return true;
  }
  if (dedupeAction === 'silent') {
    return true;
  }
  if (status === 'skipped' && ['silent_dedupe', 'action_policy_skipped', 'llm_not_requested', 'qdrant_skipped'].includes(reason)) {
    return true;
  }
  return false;
};

const shouldFinalizeSourceLastSeen = (source = {}) => {
  if (!source.is_new_since_last_poll || source.rss_status !== 'success') {
    return false;
  }
  if (!safeString(source.last_seen_state_path || '')) {
    return false;
  }
  const latest = latestFromSourceEntry(source);
  if (!Object.values(latest).some(Boolean)) {
    return false;
  }
  const processingItems = (Array.isArray(source.items) ? source.items : [])
    .filter((item) => safeString(item.audit_reason) !== 'source_last_seen_gate');
  if (processingItems.some((item) => safeString(item.audit_status) === 'failed')) {
    return false;
  }
  const terminalItems = processingItems.filter(isTerminalAuditItem);
  if (!terminalItems.length) {
    return false;
  }
  const currentLatestTerminal = terminalItems.some((item) => auditItemMatchesLatest(item, latest));
  const expectedTerminalCount = Math.max(1, numberOrZero(source.new_item_count));
  return currentLatestTerminal && terminalItems.length >= expectedTerminalCount;
};

const finalizeProcessedSourceLastSeen = (summaryValue = {}) => {
  const fs = require('fs');
  const results = [];
  for (const source of Array.isArray(summaryValue.sources) ? summaryValue.sources : []) {
    const sourceStatePath = safeString(source.last_seen_state_path || '');
    if (!sourceStatePath || !shouldFinalizeSourceLastSeen(source)) {
      continue;
    }
    const latest = latestFromSourceEntry(source);
    try {
      let previousState = {};
      if (fs.existsSync(sourceStatePath)) {
        try {
          previousState = JSON.parse(fs.readFileSync(sourceStatePath, 'utf8'));
        } catch {
          previousState = {};
        }
      }
      const latestSeen = normalizeLatestForFinalize(previousState.latest_seen || previousState.latest || latest);
      if (latestSeen && !latestMatchesForFinalize(latestSeen, latest)) {
        results.push({
          source_name: safeString(source.source_name || ''),
          feed_url: safeString(source.feed_url || ''),
          state_path: sourceStatePath,
          status: 'skipped_newer_seen'
        });
        continue;
      }
      const updatedAt = new Date().toISOString();
      const payload = {
        ...previousState,
        source_last_seen_version: 2,
        source_key: safeString(previousState.source_key || source.feed_url || ''),
        feed_url: safeString(source.feed_url || previousState.feed_url || ''),
        source_name: safeString(source.source_name || previousState.source_name || ''),
        source_type: safeString(source.source_type || previousState.source_type || ''),
        latest,
        latest_seen: latest,
        latest_processed: latest,
        pending_latest: null,
        processing_status: 'processed',
        pending_started_at: '',
        pending_updated_at: '',
        pending_attempt_count: 0,
        processed_at: updatedAt,
        last_successful_execution_id: safeString(summaryValue.execution_id || ''),
        updated_at: updatedAt
      };
      fs.writeFileSync(sourceStatePath, JSON.stringify(payload, null, 2), 'utf8');
      results.push({
        source_name: safeString(source.source_name || ''),
        feed_url: safeString(source.feed_url || ''),
        state_path: sourceStatePath,
        status: 'processed',
        title: latest.title,
        url: latest.link || latest.guid
      });
      source.source_processing_status = 'processed';
      source.last_seen_recorded_at = updatedAt;
    } catch (error) {
      results.push({
        source_name: safeString(source.source_name || ''),
        feed_url: safeString(source.feed_url || ''),
        state_path: sourceStatePath,
        status: 'error',
        error: error.message
      });
    }
  }
  return results;
};

