const original = $('Build Normalize Input').item.json || {};
const response = $json && typeof $json === 'object' ? $json : {};

const normalizeSingleLine = (value = '') => String(value ?? '')
  .replace(/\s+/g, ' ')
  .trim();

const estimateReadableChars = (html = '') => String(html ?? '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/\s+/g, ' ')
  .trim()
  .length;

const extractResponseText = (payload) => {
  if (typeof payload === 'string') {
    return payload;
  }
  if (!payload || typeof payload !== 'object') {
    return '';
  }
  for (const key of ['body', 'data', 'html', 'response', 'text']) {
    if (typeof payload[key] === 'string' && payload[key].trim()) {
      return payload[key];
    }
  }
  return '';
};

const errorMessage = normalizeSingleLine(
  response.error?.message
  || response.message
  || response.error
  || ''
);
const fetchedHtml = extractResponseText($json);
const readableChars = estimateReadableChars(fetchedHtml);
const baseTags = Array.isArray(original.extra_tags) ? original.extra_tags : [];

if (!fetchedHtml || readableChars < 200 || errorMessage) {
  return {
    json: {
      ...original,
      hn_source_page_fetched: false,
      hn_source_page_fetch_error: errorMessage || (!fetchedHtml ? 'empty response' : 'source page text shorter than 200 chars'),
      hn_source_page_url: String(original.canonical_url || '').trim()
    }
  };
}

return {
  json: {
    ...original,
    raw_html: fetchedHtml,
    raw_text: '',
    extra_tags: [...new Set([...baseTags, 'hacker-news', 'hn-source-page'])],
    hn_source_page_fetched: true,
    hn_source_page_url: String(original.canonical_url || '').trim(),
    hn_source_page_chars: readableChars
  }
};
